-- Give brand_size_charts the source URLs the charts now carry (US-3283 loop).
--
-- GENERATED FILE — do not hand-edit. Regenerate with:
--   deno run --allow-read --allow-write scripts/gen-sizing-chart-batch.mjs 00776
--
-- 36 charts across 18 brands, each read off the brand's OWN published
-- guide. Before the backfill loop started, every chart in the corpus had
-- source_url NULL — which is why the composer's "[Brand] size guide" link fell
-- through to a Google search for almost every item a seller edited.
--
-- This file is REGENERATED by each batch while it is still HELD (not yet applied
-- to prod), so one held migration carries every batch so far rather than the
-- queue growing a file per batch. Once it is applied, the next batch takes a new
-- number.
--
-- UPSERT, not insert-only. 00498's backfill is deliberately insert-only so an
-- unsourced row can never overwrite a hand-sourced pack row. This migration is
-- the other direction: it carries the source, so on conflict it WRITES.
--
-- The conflict path MUST set confidence too, and that is not a preference. An
-- 00498 residue row has source_url NULL and confidence NULL; writing only the
-- URL leaves confidence NULL, and brand_size_charts_sourced fires on the UPDATE
-- exactly as it fires on an INSERT.
--
-- Every row carries source_url AND confidence 0.85, because 00578's
-- brand_size_charts_sourced CHECK requires both — the URL alone is rejected.
-- 0.85 is the top of the packs' range: the numbers are the brand's own, and the
-- only uncertainty left is the transcription. verified stays false; that column
-- records whether a HUMAN checked, and none has.
--
-- Risk: LOW. A global reference table with deny-all RLS and no tenant data.
-- Idempotent and re-run safe: every value is derived from the committed code.

insert into public.brand_size_charts
  (brand_key, brand_label, brand_match, department, garment, category_match, rows, note, source_url, confidence, verified, updated_by) values
  ('stssy', 'Stüssy', ARRAY['stussy','stüssy']::text[], 'Men', 'Tops (tees & fleece, US alpha)', ARRAY['tee','t-shirt','shirt','top','hoodie','sweatshirt','crewneck','fleece','hooded']::text[], $json$[{"size":"XS","measurements":{"chest":"38-40","waist":"26-27"}},{"size":"S","measurements":{"chest":"42-44","waist":"28-29"}},{"size":"M","measurements":{"chest":"44-46","waist":"30-31"}},{"size":"L","measurements":{"chest":"46-48","waist":"32-34"}},{"size":"XL","measurements":{"chest":"48-50","waist":"35-36"}},{"size":"XXL","measurements":{"chest":"52-54","waist":"37"}}]$json$::jsonb, '⚠ REPLACED WITH STÜSSY''S OWN PUBLISHED NUMBERS (US-3290), and the old estimate was off by nearly a full size. It read S 36-38 / M 38-40 / L 42-44; Stüssy publishes S 42-44 / M 44-46 / L 46-48 — its published S is the same chest the old chart called an L. Anything graded against the old rows was being told a correctly tagged Stüssy tee measured a size large. Two other claims in the old note were also wrong. It said ''no national cross-map applies'': Stüssy publishes UK, IT/FR/EU, KR and JP conversions, and they are carried on the outerwear chart below. And the numbers are BODY measurements, not the body-equivalent estimate the old note described — Stüssy cuts loose, so the garment measured flat and doubled reads above these. What survives from the old note, because it is still true and still the thing to watch: vintage pieces were graded differently from current production, so on this brand the tag is a claim to check against the actual measurement. Length is no longer listed — Stüssy publishes none, and the old figures for it were part of the same estimate.', 'https://www.stussy.com/pages/size-guide', 0.85, false, 'migration:00776'),
  ('7forallmankind', '7 For All Mankind', ARRAY['7 for all mankind','7forallmankind','seven for all mankind','7fam']::text[], 'Women', 'Tops, jackets & dresses (alpha, body inches)', ARRAY['top','tee','shirt','blouse','sweater','knit','hoodie','sweatshirt','tank','jacket','coat','outerwear','blazer','vest','dress','romper','jumpsuit']::text[], $json$[{"size":"XXS","measurements":{"bust":"31.875","waist":"23","hip":"33"}},{"size":"XS","measurements":{"bust":"32.625-33.5","waist":"24-25","hip":"34-35"}},{"size":"S","measurements":{"bust":"34.25-35","waist":"26-27","hip":"36-37"}},{"size":"M","measurements":{"bust":"36.25-37.375","waist":"28-29","hip":"38-39"}},{"size":"L","measurements":{"bust":"38.625-39.75","waist":"30-31","hip":"40-41"}},{"size":"XL","measurements":{"bust":"41-42.125","waist":"31.875-32.875","hip":"42-43"}},{"size":"XXL","measurements":{"bust":"43.25-44.5","waist":"33.875-35.875","hip":"43.875-45.75"}}]$json$::jsonb, '7FAM publishes ONE women''s body chart and applies it to tops, jackets and dresses alike. Body measurements, not flat. The brand prints centimetres first; these are its own inch column with the eighths written as decimals.', 'https://7forallmankind.com/pages/size-chart', 0.85, false, 'migration:00776'),
  ('agjeans', 'AG Jeans', ARRAY['ag jeans','agjeans','adriano goldschmied']::text[], 'Women', 'Tops, jackets & dresses (alpha, body inches)', ARRAY['top','tee','shirt','blouse','sweater','knit','hoodie','sweatshirt','tank','jacket','coat','outerwear','blazer','vest','dress','romper','jumpsuit']::text[], $json$[{"size":"XXS / 00","measurements":{"bust":"30","waist":"23","hip":"33"}},{"size":"XS / 0","measurements":{"bust":"31-32","waist":"24-25","hip":"34-35"}},{"size":"S / 4","measurements":{"bust":"33-34","waist":"26-27","hip":"36-37"}},{"size":"M / 6","measurements":{"bust":"35-36","waist":"28-29","hip":"38-39"}},{"size":"L / 10","measurements":{"bust":"37-38.5","waist":"30-31","hip":"40-41.5"}},{"size":"XL / 14","measurements":{"bust":"39.5-41","waist":"32-33","hip":"42.5-44"}},{"size":"XXL / 18","measurements":{"bust":"42-43.5","waist":"34","hip":"45-46.5"}}]$json$::jsonb, 'AG publishes one women''s body chart keyed on denim waist, with alpha and US numeric alongside. The alpha rows are here; the denim-waist rows are on AG''s jeans chart. Body measurements, not flat.', 'https://www.agjeans.com/pages/womens-size-guide', 0.85, false, 'migration:00776'),
  ('agjeans', 'AG Jeans', ARRAY['ag jeans','agjeans','adriano goldschmied']::text[], 'Men', 'Tops & outerwear (alpha, body inches)', ARRAY['top','tee','shirt','polo','sweater','knit','hoodie','sweatshirt','jacket','coat','outerwear','blazer','vest']::text[], $json$[{"size":"XS","measurements":{"chest":"35.5-36.5","waist":"28-29","hip":"34.5-35.5"}},{"size":"S","measurements":{"chest":"37.5-38.5","waist":"30-31","hip":"36.5-37.5"}},{"size":"M","measurements":{"chest":"39.5-40.5","waist":"32-33","hip":"38.5-39.5"}},{"size":"L","measurements":{"chest":"41.5-42.5","waist":"34-36","hip":"40.5-42.5"}},{"size":"XL","measurements":{"chest":"43.5-44.5","waist":"38-40","hip":"44.5-46.5"}},{"size":"XXL","measurements":{"chest":"46.5-48","waist":"42-44","hip":"48-49.5"}}]$json$::jsonb, 'AG publishes one men''s body chart keyed on denim waist (28-44), with the alpha and chest columns beside it. Body measurements, not flat.', 'https://www.agjeans.com/pages/mens-size-guide', 0.85, false, 'migration:00776'),
  ('americaneagle', 'American Eagle', ARRAY['american eagle','americaneagle','aerie']::text[], 'Women', 'Tops & outerwear (alpha/numeric, body inches)', ARRAY['top','tee','shirt','blouse','sweater','knit','hoodie','sweatshirt','tank','jacket','coat','outerwear','blazer','vest']::text[], $json$[{"size":"XXS / 00","measurements":{"bust":"31"}},{"size":"XS / 0","measurements":{"bust":"32"}},{"size":"XS / 2","measurements":{"bust":"33"}},{"size":"S / 4","measurements":{"bust":"34"}},{"size":"S / 6","measurements":{"bust":"35"}},{"size":"M / 8","measurements":{"bust":"36"}},{"size":"M / 10","measurements":{"bust":"37.5"}},{"size":"L / 12","measurements":{"bust":"39"}},{"size":"L / 14","measurements":{"bust":"40.5"}},{"size":"XL / 16","measurements":{"bust":"42"}},{"size":"XXL / 18","measurements":{"bust":"44"}}]$json$::jsonb, 'AE''s women''s tops chart carries BUST ONLY, and AE publishes no separate outerwear chart — its jackets are sized off this one. Body measurements.', 'https://www.ae.com/us/en/content/help/women-size-chart', 0.85, false, 'migration:00776'),
